import{_ as t,g as a,e as r,a4 as o}from"./chunks/framework.CEYJDsBW.js";const p=JSON.parse('{"title":"Data & Resource Packs","description":"","frontmatter":{},"headers":[],"relativePath":"en/ageratum/26.1/packs/index.md","filePath":"en/ageratum/26.1/packs/index.md"}'),d={name:"en/ageratum/26.1/packs/index.md"};function s(n,e,i,c,l,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="data-resource-packs" tabindex="-1">Data &amp; Resource Packs <a class="header-anchor" href="#data-resource-packs" aria-label="Permalink to &quot;Data &amp; Resource Packs&quot;">​</a></h1><p>Ageratum reads guides during client resource reload. When distributing to other players, bundle Markdown files, illustrations, and structure previews with your mod&#39;s resources or a client resource pack. The server can notify a player to open a document ID, while the content itself comes from the player&#39;s local client.</p><table tabindex="0"><thead><tr><th>Goal</th><th>Entrypoint</th></tr></thead><tbody><tr><td>Create a guide from an empty directory, check language fallback and preview</td><td><a href="./layout.html">Resource Pack Layout</a></td></tr><tr><td>Customize directory titles, sorting, and colors</td><td><a href="./metadata.html">Page Metadata</a></td></tr><tr><td>Open articles from specific items or item components</td><td><a href="./bindings.html">Item Bindings</a></td></tr><tr><td>Insert callout boxes, row layouts, and formulas</td><td><a href="./blocks.html">Block Tags &amp; Layout</a></td></tr><tr><td>Display items, blocks, entities, and recipe placeholders</td><td><a href="./content.html">Game Objects &amp; Recipes</a></td></tr><tr><td>Use localized text, keybinds, interactive styles, and images</td><td><a href="./inline.html">Inline Tags &amp; Images</a></td></tr><tr><td>Preview NBT or SNBT inside a page</td><td><a href="./structures.html">Structure Previews &amp; Fields</a></td></tr><tr><td>Project structures from commands or body text</td><td><a href="./export.html">Structure Projection</a></td></tr><tr><td>Define layouts, panels, component colors, and textures</td><td><a href="./appearance/">Layout JSON</a></td></tr><tr><td>Customize the guidebook item model and translations</td><td><a href="./guidebook.html">Guidebook Item Appearance</a></td></tr></tbody></table><p>The guide registries register component factories in code, and resource pack authors use those factories via tags. The <code>data/</code> directory of a regular server-side data pack has no standalone guide discovery or component registration entrypoint. The built-in <code>recipe</code> tag reads the ID, and currently leaves a blank placeholder. <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/feat/markdown/GuideDocumentCache.java" target="_blank" rel="noreferrer">Document cache</a> · <a href="https://github.com/Anvil-Dev/Ageratum/blob/36bf4ce16017ebc532a369c56f972dfb73d272a0/src/main/java/dev/anvilcraft/resource/ageratum/client/AgeratumClient.java" target="_blank" rel="noreferrer">Client registration</a></p>',4)])])}const h=t(d,[["render",s]]);export{p as __pageData,h as default};
